def categorize_hemoglobin_levels(hemoglobin_levels):
    categories = []
    for level in hemoglobin_levels:
        if level >= 12.0:
            categories.append("Normal")
        elif 10.0 <= level < 12.0:
            categories.append("Mild Anemia")
        elif 8.0 <= level < 10.0:
            categories.append("Moderate Anemia")
        else:
            categories.append("Severe Anemia")
    return categories

def parse_log_file(log_file):
    failed_ip_addresses = set()

    try:
        with open(log_file, 'r') as file:
            for line in file:
                if "Failed login attempt" in line:
                    ip_address = line.split(']')[-1].strip()
                    failed_ip_addresses.add(ip_address)

    except FileNotFoundError:
        print(f"Error: File '{log_file}' not found.")
    except Exception as e:
        print(f"Error: {e}")

    return list(failed_ip_addresses)

def calculate_average_weight(bowling_balls):
    if not bowling_balls:
        return 0.0
