    average_weight = total_weight / num_balls
    return round(average_weight, 2)

def calculate_annualized_return(monthly_returns):
    total_return = 1
    for monthly_return in monthly_returns:
        total_return *= (1 + monthly_return)
    annualized_return = total_return ** (1 / len(monthly_returns)) - 1
    return annualized_return * 12

