def calculate_carbon_footprint(orders):
    total_emission_A = 0
    total_emission_B = 0

    for order in orders:
        company = order["company"]
        distance = order["distance"]

        if company == "A":
            emission = distance * 0.25
            total_emission_A += emission
        else:
            emission = distance * 0.15
            total_emission_B += emission

    return {
        "total_emission_A": total_emission_A,
        "total_emission_B": total_emission_B
    }

