def calculate_average_speed(race_data):
    athlete_speeds = {}
    for athlete, distance, time in race_data:
        speed = distance / time
        if athlete in athlete_speeds:
            athlete_speeds[athlete].append(speed)
        else:
            athlete_speeds[athlete] = [speed]

    average_speeds = {}
    for athlete, speeds in athlete_speeds.items():
        average_speed = sum(speeds) / len(speeds)
        average_speeds[athlete] = average_speed

    return average_speeds

