def can_form_palindrome(string):
    # Convert the string to lowercase and remove non-alphabetic characters
    cleaned_string = ''.join(char for char in string.lower() if char.isalpha())

    # Count the frequency of each character
    char_counts = {}
    for char in cleaned_string:
        char_counts[char] = char_counts.get(char, 0) + 1

    # Check if at most one character has an odd count
    odd_count = sum(count % 2 for count in char_counts.values())

    return odd_count <= 1

