    negative_words = ['bad', 'terrible', 'failure', 'sad', 'problem', 'stress']

    positive_count = 0
    negative_count = 0
    neutral_count = 0

    for message in messages:
        message_words = message.lower().split()
        positive_match = any(word in positive_words for word in message_words)
        negative_match = any(word in negative_words for word in message_words)

        if positive_match and negative_match:
            positive_count += 1
            negative_count += 1
        elif positive_match:
            positive_count += 1
        elif negative_match:
            negative_count += 1
        else:
            neutral_count += 1

    return {'positive': positive_count, 'negative': negative_count, 'neutral': neutral_count}

