def calculate_gini_coefficient(income_values):
    if not income_values:
        return 0.0

    n = len(income_values)
    total_income = sum(income_values)
    mean_income = total_income / n

    numerator = sum(abs(x - y) for i, x in enumerate(income_values) for j, y in enumerate(income_values) if i != j)
    denominator = 2 * n * n * mean_income

    if denominator == 0:
        return 0.0
    else:
        gini_coefficient = numerator / denominator
        return gini_coefficient

