    class_ages = {}

    for passenger in passenger_data:
        passenger_class = passenger["class"]
        age = passenger["age"]

        if age is not None:
            if passenger_class in class_ages:
                class_ages[passenger_class].append(age)
            else:
                class_ages[passenger_class] = [age]

    average_ages = {}
    for class_name, ages in class_ages.items():
        if ages:
            average_age = sum(ages) / len(ages)
            average_ages[class_name] = average_age
        else:
            average_ages[class_name] = 0

    return average_ages
```

