    zones = []
    for rate in heart_rates:
        if rate < 60:
            zones.append("Very Light")
        elif rate < 80:
            zones.append("Light")
        elif rate < 100:
            zones.append("Moderate")
        elif rate < 140:
            zones.append("Hard")
        else:
            zones.append("Maximum")
    return zones
```

