def track_sentiments(scores):
    sentiment_counts = {
        "positive": 0,
        "negative": 0,
        "neutral": 0
    }

    for score in scores:
        if score > 0:
            sentiment_counts["positive"] += 1
        elif score < 0:
            sentiment_counts["negative"] += 1
        else:
            sentiment_counts["neutral"] += 1

    return sentiment_counts
```

