def determine_mood(episodes):
    happy_count = 0
    sad_count = 0

    for episode in episodes:
        for scene in episode:
            if scene == 'H':
                happy_count += 1
            elif scene == 'S':
                sad_count += 1

    if happy_count > sad_count:
        return "Happy"
    elif sad_count > happy_count:
        return "Sad"
    else:
        return "Neutral"
```

