def analyze_dna_sequences(reference_sequence, target_sequences):
    def count_mutations(ref_seq, target_seq):
        mutations = 0
        if len(ref_seq) != len(target_seq):
            raise ValueError("Sequences must have the same length.")
        for i in range(len(ref_seq)):
            if ref_seq[i] != target_seq[i]:
                mutations += 1
        return mutations

    mutation_counts = []
    for target_seq in target_sequences:
        unique_mutations = count_mutations(reference_sequence, target_seq)
        mutation_counts.append(unique_mutations)
    return mutation_counts

