        'unique_suggestions': unique_suggestions
    }

def move_robot(commands):
    x, y = 0, 0  # Start at the origin (0, 0)

    for command in commands:
        direction = command[0]
        steps = int(command[1:])

        if direction == 'U':
            y += steps
        elif direction == 'D':
            y -= steps
        elif direction == 'L':
            x -= steps
        elif direction == 'R':
            x += steps

    return (x, y)

