def is_valid_unix_path(path):
    import re

    # Check if the path starts with a slash (absolute path) or not (relative path)
    if path.startswith('/'):
        absolute_path = True
    else:
        absolute_path = False

    # Define a regular expression pattern for valid UNIX file paths
    pattern = r'^(/+[^/]+)*/?$'

    # Check if the path matches the pattern
    if re.match(pattern, path):
        # Check if the path ends with a slash (except for the root path)
        if path.endswith('/') and path != '/':
            return False
        # Check if there are consecutive slashes (except for the case where the path begins with exactly two slashes)
        elif '//' in path[2:]:
            return False
        else:
            return True
    else:
        return False

