Here's a Python function that implements the Observer design pattern for a simple weather station system:

```python
from abc import ABC, abstractmethod

class Subject(ABC):
    """
    Abstract Subject class that defines the observer pattern interface.
    """
    @abstractmethod
    def register_observer(self, observer):
        pass

    @abstractmethod
    def deregister_observer(self, observer):
        pass

    @abstractmethod
    def notify_observers(self):
        pass

class Observer(ABC):
    """
    Abstract Observer class that defines the observer interface.
    """
    @abstractmethod
    def update(self, temperature, humidity, pressure):
        pass

class WeatherStation(Subject):
    """
    Concrete Subject class that represents the weather station.
    """
    def __init__(self):
        self.observers = []
        self.temperature = None
        self.humidity = None
        self.pressure = None

    def register_observer(self, observer):
        self.observers.append(observer)

    def deregister_observer(self, observer):
        self.observers.remove(observer)

    def notify_observers(self):
        for observer in self.observers:
            observer.update(self.temperature, self.humidity, self.pressure)

    def set_weather_data(self, temperature, humidity, pressure):
        self.temperature = temperature
        self.humidity = humidity
        self.pressure = pressure
        self.notify_observers()

class CurrentConditionsDisplay(Observer):
    """
    Concrete Observer class that displays the current weather conditions.
    """
    def update(self, temperature, humidity, pressure):
        print(f"Current conditions: {temperature}°C, {humidity}% humidity, {pressure} hPa")

def weather_station_observer_pattern(weather_station, current_display, temperature, humidity, pressure):
    weather_station.register_observer(current_display)
    weather_station.set_weather_data(temperature, humidity, pressure)

# Usage example
weather_station = WeatherStation()
current_display = CurrentConditionsDisplay()
