def analyze_book_ratings(ratings):
    from collections import Counter

    rating_counts = Counter(ratings)
    total_ratings = sum(rating_counts.values())
    avg_frequency = total_ratings / len(rating_counts)

    anomalies = []
    for rating, count in rating_counts.items():
        if count > 2 * avg_frequency:
            anomalies.append((rating, count))

    return anomalies

