def calculate_launch_window(mars_year, earth_year):
    def gcd(a, b):
        while b != 0:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return (a * b) // gcd(a, b)

    launch_cycle = lcm(mars_year, earth_year)
    return launch_cycle

