    for sale in sales_data:
        region = sale['region']
        product = sale['product']
        sales = sale['sales']

        # Initialize the region dictionary if not present
        if region not in region_sales:
            region_sales[region] = []

        # Add the product and sales to the region dictionary
        region_sales[region].append((product, sales))

    # Sort the products in each region by sales in descending order
