def longest_unique_substring(string):
    if not string:
        return ""

    seen = {}
    max_length = 0
    start = 0
    max_start = 0

    for i, char in enumerate(string):
        if char in seen and seen[char] >= start:
            start = seen[char] + 1
        else:
            max_length = max(max_length, i - start + 1)
            if max_length == i - start + 1:
                max_start = start

        seen[char] = i

