def track_animal_sightings(sightings):
    result = {}

    for sighting in sightings:
        animal = sighting['animal']
        location = sighting['location']
        count = sighting['count']

        if animal not in result:
            result[animal] = {'total_count': 0, 'locations': []}

        result[animal]['total_count'] += count
        if location not in result[animal]['locations']:
            result[animal]['locations'].append(location)

    return result
```

