def analyze_sentiment(statements):
    word_freq = {}

    for statement in statements:
        # Remove punctuation and convert to lowercase
        cleaned_statement = ''.join(char for char in statement.lower() if char.isalnum() or char == ' ')
        words = cleaned_statement.split()

        for word in words:
            if word in word_freq:
                word_freq[word] += 1
            else:
                word_freq[word] = 1

    return word_freq

