def rank_players(players):
    def calculate_efficiency(player):
        goals = player['goals']
        assists = player['assists']
        minutes_played = player['minutes_played']
        if minutes_played == 0:
            return float('inf')
        else:
            return (goals + assists) / minutes_played

    ranked_players = sorted(players, key=calculate_efficiency, reverse=True)
    return [player['name'] for player in ranked_players]

